# ============================================================
# SaleHop update -- Manage menu on listings + a fully customizable sign
# ============================================================
#
# Two changes in this one script:
#
# 1) MANAGE MENU
#    Tapping the wrench (Manage) on one of your own listings -- whether
#    you got there from the Map screen or by opening a listing from My
#    Listings -- now pops up a small menu right there with Edit Listing,
#    Print Sign, Feature ($10), Share, and Delete, instead of just
#    jumping you to My Listings. Everything works the same as the
#    buttons already in My Listings (same Edit form, same Stripe
#    checkout for Feature, same confirm-before-delete) -- it's the same
#    actions, just reachable from one small menu wherever you are.
#
# 2) CUSTOM PRINTABLE SIGN
#    The "Print Sign" page now has options above the sign itself:
#      - Orientation: Portrait or Landscape
#      - Arrow Direction: Up / Down / Left / Right / No Arrow (pick "No
#        Arrow" for posting somewhere that isn't pointing toward the
#        sale, like a community board)
#      - Paper Size: 8.5"x11", 11"x17", 13"x19", or "Large Sign" -- which
#        prints as 6 separate letter-size pages you tape together into
#        one big roadside banner, with a small "Tile X of 6" label
#        printed in the corner of each page to guide assembly.
#    Changing any of these updates the sign live before you print or
#    save as a PDF.
#
# Files this script replaces:
#   1. components/AppShell.js
#   2. components/AccountScreen.js
#   3. components/ListingSheet.js
#   4. app/listing/[id]/sign/page.js
#   5. app/listing/[id]/sign/SignBuilder.js   (new file)
#   6. app/globals.css
#
# Run this from inside your salehop project folder (where package.json
# lives) -- same as every script before this one.

# ---------- Safety check: are we actually in the right folder? ----------
if (-not (Test-Path "package.json")) {
  Write-Host ""
  Write-Host "STOP: There's no package.json in this folder." -ForegroundColor Red
  Write-Host "You need to 'cd' into your actual salehop project folder first," -ForegroundColor Red
  Write-Host "then run this script again from there." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
if (-not (Test-Path ".git")) {
  Write-Host ""
  Write-Host "STOP: This folder has package.json but no .git folder," -ForegroundColor Red
  Write-Host "so it isn't connected to your GitHub/Vercel project." -ForegroundColor Red
  Write-Host "Make sure you're in the folder you originally cloned, not a copy." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
Write-Host "Found package.json and .git here -- this looks like the right folder." -ForegroundColor Cyan
Write-Host ""

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)
Write-Host ""

# ---------- components/AppShell.js ----------
[System.IO.Directory]::CreateDirectory("components") | Out-Null
$b64_components_AppShell_js = @"

"@
[System.IO.File]::WriteAllBytes("components/AppShell.js", [Convert]::FromBase64String($b64_components_AppShell_js))
Write-Host "Wrote components/AppShell.js" -ForegroundColor Green

# ---------- components/AccountScreen.js ----------
[System.IO.Directory]::CreateDirectory("components") | Out-Null
$b64_components_AccountScreen_js = @"

"@
[System.IO.File]::WriteAllBytes("components/AccountScreen.js", [Convert]::FromBase64String($b64_components_AccountScreen_js))
Write-Host "Wrote components/AccountScreen.js" -ForegroundColor Green

# ---------- components/ListingSheet.js ----------
[System.IO.Directory]::CreateDirectory("components") | Out-Null
$b64_components_ListingSheet_js = @"

"@
[System.IO.File]::WriteAllBytes("components/ListingSheet.js", [Convert]::FromBase64String($b64_components_ListingSheet_js))
Write-Host "Wrote components/ListingSheet.js" -ForegroundColor Green

# ---------- app/listing/[id]/sign/page.js ----------
[System.IO.Directory]::CreateDirectory("app/listing/[id]/sign") | Out-Null
$b64_app_listing_id_sign_page_js = @"

"@
[System.IO.File]::WriteAllBytes("app/listing/[id]/sign/page.js", [Convert]::FromBase64String($b64_app_listing_id_sign_page_js))
Write-Host "Wrote app/listing/[id]/sign/page.js" -ForegroundColor Green

# ---------- app/listing/[id]/sign/SignBuilder.js ----------
[System.IO.Directory]::CreateDirectory("app/listing/[id]/sign") | Out-Null
$b64_app_listing_id_sign_SignBuilder_js = @"

"@
[System.IO.File]::WriteAllBytes("app/listing/[id]/sign/SignBuilder.js", [Convert]::FromBase64String($b64_app_listing_id_sign_SignBuilder_js))
Write-Host "Wrote app/listing/[id]/sign/SignBuilder.js" -ForegroundColor Green

# ---------- app/globals.css ----------
[System.IO.Directory]::CreateDirectory("app") | Out-Null
$b64_app_globals_css = @"

"@
[System.IO.File]::WriteAllBytes("app/globals.css", [Convert]::FromBase64String($b64_app_globals_css))
Write-Host "Wrote app/globals.css" -ForegroundColor Green


# ---------- Verify everything actually got written ----------
$checkFiles = @(
  "components/AppShell.js",
  "components/AccountScreen.js",
  "components/ListingSheet.js",
  "app/listing/[id]/sign/page.js",
  "app/listing/[id]/sign/SignBuilder.js",
  "app/globals.css"
)

$missing = $checkFiles | Where-Object { -not (Test-Path -LiteralPath $_) }
if ($missing.Count -gt 0) {
  Write-Host ""
  Write-Host "STOP: These files did not get written:" -ForegroundColor Red
  $missing | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
  Write-Host "Nothing was committed. Please re-run this script from the correct folder." -ForegroundColor Red
  exit 1
}
Write-Host ""
Write-Host "All files verified on disk." -ForegroundColor Green
Write-Host ""

Write-Host "All files written. Reviewing git status..." -ForegroundColor Cyan
git status

$commit = Read-Host "Type Y and press Enter to commit and push these changes (or anything else to stop here)"
if ($commit -eq "Y" -or $commit -eq "y") {
  git add -A
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git add failed -- see the error above. Nothing was committed or pushed." -ForegroundColor Red
    exit 1
  }

  git commit -m "Add manage menu (Edit/Print/Feature/Share/Delete) and customizable printable sign"
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git commit failed -- see the error above (this also happens if there was nothing new to commit). Nothing was pushed." -ForegroundColor Red
    exit 1
  }

  git push
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git push failed -- see the error above. Your changes are committed locally but NOT on GitHub/Vercel yet." -ForegroundColor Red
    exit 1
  }

  Write-Host ""
  Write-Host "Pushed successfully! Vercel should pick this up and deploy automatically." -ForegroundColor Green
} else {
  Write-Host "Stopped before committing. Your files are updated locally -- run git add -A, git commit, git push whenever you are ready." -ForegroundColor Yellow
}
